import json, os, re, shlex, sys
from pathlib import Path

EXPECTED = {
    "diagnostic": {"Common", "ng039_gw_q0_q1_d2"},
    "default": {"Common", "ContentApp", "IoTTestApp", "NBTestApp", "PGCS", "NRNCS"},
}
COMPILER = os.path.realpath("/usr/bin/x86_64-linux-gnu-g++-13")
OBSERVER = "NG_GW_QUEUE_TEST_OBSERVATION"
REQUIRED = {"-O0", "-g", "-g3", "-Wall", "-fmessage-length=0", "-pthread", "-Wno-deprecated", "-lpthread", "-lrt", "-fno-omit-frame-pointer", "-c"}
PAIRED = {"-o", "-MF", "-MT", "-I", "-isystem", "-iquote"}
JOINED = ("-isystem", "-iquote", "-MF", "-MT", "-I", "-o")
DEP = {"-MD", "-MMD", "-MP"}
SHELL_CONTROL = set(";|&<>")

def reject(message):
    raise ValueError(message)

def norm_path(value, directory):
    p = Path(value)
    return (p if p.is_absolute() else directory / p).resolve(strict=False)

def macro_parts(value):
    m = re.fullmatch(r"([A-Za-z_][A-Za-z0-9_]*)(\([^)]*\))?(?:=(.*))?", value)
    if not m:
        reject("malformed -D/-U operand")
    return m.group(1), m.group(2), m.group(3)

def target_from_output(output_path):
    parts = output_path.parts
    found = []
    for i, part in enumerate(parts[:-1]):
        if part == "CMakeFiles" and parts[i + 1].endswith(".dir"):
            found.append(parts[i + 1][:-4])
    if len(found) != 1:
        reject("target cannot be uniquely derived from actual -o output")
    return found[0]

def entry_tokens(entry):
    directory = Path(entry["directory"]).resolve(strict=False)
    command = entry.get("command")
    arguments = entry.get("arguments")
    if command is not None:
        if not isinstance(command, str):
            reject("command must be a string")
        words = shlex.split(command, posix=True)
        if any(c in command for c in "$`;&|<>"):
            reject("shell expansion/control syntax is unsupported")
        if arguments is not None and (not isinstance(arguments, list) or words != arguments):
            reject("command/arguments disagreement")
    elif isinstance(arguments, list):
        words = list(arguments)
    else:
        reject("compile entry has neither command nor arguments")
    if not words or not all(isinstance(x, str) for x in words):
        reject("empty or malformed argv")
    if os.path.realpath(words[0]) != COMPILER:
        reject("compiler identity mismatch")
    if any(x.startswith("@") for x in words):
        reject("response files are unsupported")
    if any(x.startswith("-Wp") or x == "-Xpreprocessor" for x in words):
        reject("forwarded preprocessor arguments are unsupported")
    return words, directory

def validate_compile_database(entries, profile):
    if profile not in EXPECTED or not isinstance(entries, list) or not entries:
        reject("unknown profile or empty compile database")
    seen = set()
    for entry in entries:
        if not isinstance(entry, dict) or not {"directory", "file"}.issubset(entry):
            reject("malformed compile entry")
        argv, directory = entry_tokens(entry)
        target_outputs = []
        sources = []
        standards = []
        optimizations = []
        macros = []
        observed_defines = []
        i = 1
        while i < len(argv):
            token = argv[i]
            if token in PAIRED:
                i += 1
                if i >= len(argv) or not argv[i] or argv[i].startswith("-"):
                    reject("missing/malformed option operand")
                value = argv[i]
                if token == "-o":
                    target_outputs.append(value)
                i += 1
                continue
            if token in ("-D", "-U"):
                op = token
                i += 1
                if i >= len(argv):
                    reject("missing macro operand")
                raw = argv[i]
                base, function_like, value = macro_parts(raw)
                macros.append((op, base, function_like, value, raw))
                if base == OBSERVER:
                    observed_defines.append((op, function_like, value, raw))
                i += 1
                continue
            if token.startswith("-D") or token.startswith("-U"):
                op, raw = token[:2], token[2:]
                base, function_like, value = macro_parts(raw)
                macros.append((op, base, function_like, value, raw))
                if base == OBSERVER:
                    observed_defines.append((op, function_like, value, raw))
                i += 1
                continue
            if token.startswith("-std="):
                standards.append(token)
                i += 1
                continue
            if token.startswith("-O"):
                optimizations.append(token)
                if token != "-O0":
                    reject("optimization override")
                i += 1
                continue
            if token in REQUIRED or token in DEP:
                i += 1
                continue
            matched = False
            for prefix in JOINED:
                if token.startswith(prefix) and len(token) > len(prefix):
                    value = token[len(prefix):]
                    if not value or any(c in value for c in SHELL_CONTROL):
                        reject("malformed joined operand")
                    if prefix == "-o":
                        target_outputs.append(value)
                    matched = True
                    break
            if matched:
                i += 1
                continue
            if token.startswith("-"):
                reject("unsupported compiler/driver option: " + token)
            if any(c in token for c in SHELL_CONTROL):
                reject("shell control token")
            sources.append(token)
            i += 1
        if len(target_outputs) != 1:
            reject("exactly one actual -o output is required")
        output_path = norm_path(target_outputs[0], directory)
        target = target_from_output(output_path)
        if target not in EXPECTED[profile]:
            reject("unexpected target: " + target)
        seen.add(target)
        if "output" in entry and norm_path(entry["output"], directory) != output_path:
            reject("output metadata disagrees with actual -o path")
        if len(sources) != 1 or norm_path(sources[0], directory) != norm_path(entry["file"], directory):
            reject("source operand disagrees with entry file")
        if standards != ["-std=gnu++20"]:
            reject("effective language mode must be exactly gnu++20")
        if not optimizations or any(x != "-O0" for x in optimizations):
            reject("effective optimization must be -O0 only")
        if not REQUIRED.issubset(set(argv)):
            reject("required project/debug flags missing")
        if profile == "default" and observed_defines:
            reject("observer macro defined or undefined in default profile")
        if profile == "diagnostic" and target in {"Common", "ng039_gw_q0_q1_d2"}:
            if observed_defines != [("-D", None, "1", OBSERVER + "=1")]:
                reject("diagnostic observer macro must be exactly one object-like =1 define")
    if seen != EXPECTED[profile]:
        reject("target census mismatch")
    return {"profile": profile, "targets": sorted(seen), "entries": len(entries)}

if __name__ == "__main__":
    with open(sys.argv[1], encoding="utf-8") as f:
        data = json.load(f)
    print(json.dumps(validate_compile_database(data, sys.argv[2]), sort_keys=True))

