import json, os, shlex, sys

COMPILER = os.path.realpath("/usr/bin/x86_64-linux-gnu-g++-13")
REQUIRED = ("-static", "-static-libgcc", "-static-libstdc++")

def validate_link_tokens(argv):
    if not isinstance(argv, list) or not argv:
        raise ValueError("empty linker argv")
    if os.path.realpath(argv[0]) != COMPILER:
        raise ValueError("linker compiler identity mismatch")
    if any(token.startswith("@") for token in argv):
        raise ValueError("response files are unsupported")
    if any(argv.count(flag) != 1 for flag in REQUIRED):
        raise ValueError("required standalone static linker flags must each occur once")
    for i, token in enumerate(argv):
        if token in {"-Bdynamic", "-dynamic", "-shared", "--dynamic-linker"}:
            raise ValueError("conflicting dynamic link mode")
        if token.startswith("-Wl,"):
            forwarded = token[4:].split(",")
            if any(x in {"-Bdynamic", "-dynamic", "--dynamic-linker"} or x.startswith("--dynamic-linker=") for x in forwarded):
                raise ValueError("conflicting forwarded dynamic link mode")
            if any(forwarded[j] == "-B" and j + 1 < len(forwarded) and forwarded[j + 1] == "dynamic" for j in range(len(forwarded))):
                raise ValueError("conflicting forwarded -B dynamic mode")
        if token == "-Xlinker" and i + 1 < len(argv):
            next_token = argv[i + 1]
            if next_token in {"-Bdynamic", "-dynamic", "-shared", "--dynamic-linker"} or next_token.startswith("--dynamic-linker="):
                raise ValueError("conflicting -Xlinker dynamic mode")
    return "link flags PASS"

if __name__ == "__main__":
    try:
        argv = shlex.split(sys.stdin.read(), posix=True)
        print(validate_link_tokens(argv))
    except Exception as exc:
        print("link check failed: " + str(exc), file=sys.stderr)
        raise SystemExit(2)
